    close = ex.live_prices(ticker)
    r = ex.log_returns(close)
    return close, r, ex.summary(r.values)


@st.cache_data(show_spinner=False)
def market_table():
    return ex.market_table()


@st.cache_data(show_spinner=False)
def fitted():
    return ex.fitted_settings()


@st.cache_data(show_spinner=False, max_entries=60)
def run_mixes(a1, a2, v1, days, seed):
    """{mix: (returns or None, runaway day or None)} for the three trader mixes."""
    p, burn = fitted()
    p = dict(p, a2=a2, v1=v1)
    out = {}
    for m in ex.MIXES:
        r, err = ex.run_mix(p, m, a1, days, seed, burn)
        out[m] = (r, None if err is None else err.day)
    return out


@st.cache_data(show_spinner=False)
def default_mixes(seed=7, days=10000):
    p, _ = fitted()
    return run_mixes(float(p["a1"]), float(p["a2"]), float(p["v1"]), days, seed)


@st.cache_data(show_spinner=False)
def seed_runs(mix, days=CHECK_DAYS, seeds=tuple(SEEDS)):
    """The same mix at the S&P fit over several seeds: {seed: (returns or None, runaway day)}."""
    p, burn = fitted()
    out = {}
    for s in seeds:
        r, err = ex.run_mix(p, mix, p["a1"], days, s, burn)
        out[s] = (r, None if err is None else err.day)
    return out


@st.cache_data(show_spinner=False)
def runaway_path(seed, day):
    p, _ = fitted()
    return ex.runaway_path(p, "chartists", 0.0, seed, int(day))


# ------------------------------------------------------------------ charts
def style(fig, height=380, logx=False, logy=False, xtitle="", ytitle="", legend=True):
    fig.update_layout(template="plotly_dark", height=height, margin=dict(l=10, r=10, t=30, b=10),
                      paper_bgcolor="rgba(0,0,0,0)", plot_bgcolor=CARD, hovermode="closest",
                      showlegend=legend, font=dict(size=12),
                      legend=dict(orientation="h", y=1.1, x=0, font=dict(size=11), bgcolor="rgba(0,0,0,0)"))
    # "-" lets plotly choose (dates or numbers); forcing "linear" left the date axis empty
    fig.update_xaxes(type="log" if logx else "-", gridcolor=GRID, zeroline=False, title=xtitle)
    fig.update_yaxes(type="log" if logy else "-", gridcolor=GRID, zeroline=False, title=ytitle)
    return fig


def show(fig):
    st.plotly_chart(fig, use_container_width=True, config={"displaylogo": False})


def mix_line(m, width=2.2):
    _, _, color, dash = MIX[m]
    return dict(color=color, dash=dash, width=width)


def tail_chart(series, height=380, bell=True, guide=True):
    """Share of days with a move at least this big, on log-log axes.
    series: list of (label, returns, line dict)."""
    fig = go.Figure()
    for label, r, line in series:
        x, y = ex.tail_curve(np.asarray(r))
        fig.add_scatter(x=x, y=y, name=label, mode="lines", line=line,
                        hovertemplate=f"{label}<br>%{{x:.1f}} sd or more: %{{y:.2%}} of days<extra></extra>")
    if bell:
        g = np.linspace(0.1, 6, 80)
        fig.add_scatter(x=g, y=[ex.bell_big_days(1, v) for v in g], name="Bell curve", mode="lines",
                        line=dict(color=BELL, dash="dot", width=2), hoverinfo="skip")
    if guide and series:
        x, y = ex.tail_curve(np.asarray(series[0][1]))
        y0 = float(np.interp(3.0, x, y))
        fig.add_scatter(x=[2, 30], y=[y0 * (2 / 3) ** -3, y0 * (30 / 3) ** -3], name="Slope 3 (cubic law)",
                        mode="lines", line=dict(color="#5C5E6B", dash="longdash", width=1), hoverinfo="skip")
    fig.update_yaxes(range=[-5, 0.05])
    fig.update_xaxes(range=[-1, 1.6])
    return style(fig, height, logx=True, logy=True, xtitle="Move size (standard deviations)",
                 ytitle="Share of days at least this big")


def mix_card(m, s, runaway_day=None, closest=False):
    name, sub, color, _ = MIX[m]
    if s is None:
        body = f"<div class='n' style='color:{DOWN};font-size:1rem'>Ran away on day {runaway_day:,}</div>" \
               f"<div class='muted'>a bubble or crash that never came back</div>"
    else:
        body = (f"<div class='n'>{s['tail']:.2f} <span class='muted'>tail</span></div>"
                f"<div class='muted'>kurtosis {s['kurtosis']:.1f} · memory {s['memory']:.2f}</div>")
    tag = " <span class='badge' style='background:#2A2B33;color:#E6E6EA'>closest</span>" if closest else ""
    return (f"<div class='card' style='border-top:3px solid {color}'><div class='t' style='color:{color}'>"
            f"{name}{tag}</div><div class='muted'>{sub}</div>{body}</div>")


def fmt_table(df):
    return df.style.format(precision=2)

