"""Shared look and cached data for every page of the web app (app.py).

Colors mean one thing each, on every page (Okabe-Ito colors, readable with color blindness):
    white        the real market
    blue         fundamentalists only (the bell-curve base case)
    orange       chartists without herding
    pink-purple  chartists who herd (the full model)
    gray dots    the bell curve
    green / coral  only gains / losses (and big up / down days), always with an arrow
Buttons, sliders and switches are neutral gray, so color on a page always means data.
"""
import numpy as np
import pandas as pd
import plotly.graph_objects as go
import streamlit as st

from herding import explore as ex
from herding import model

REAL, BELL, UP, DOWN = "#F2F4F8", "#7D8594", "#34D399", "#FF7A6B"   # down = coral
GRID, CARD, MUTED, PANEL = "#1F2632", "#11151C", "#8B93A3", "#0F1318"
MONO = "'JetBrains Mono', ui-monospace, SFMono-Regular, Menlo, monospace"
MIX = {  # key: (name, one-line meaning, color, line style)
    "fundamentalists": ("Fundamentalists only", "trade on the true value", "#56B4E9", "dot"),
    "chartists": ("Chartists, no herding", "follow the trend alone", "#E69F00", "dash"),
    "herding": ("Chartists who herd", "follow the trend and the crowd", "#D98BBE", "solid"),
}
PICK = ["#F2F2F5", "#F0E442", "#4FD1C5", "#FF9F7F", "#A3E635", "#93C5FD"]   # labels for markets you pick
SEEDS = range(5)                  # histories behind each check (more seeds = steadier, slower)
CHECK_DAYS = 10000

HELP = {
    "tail": "Tail exponent: how fast big days get rarer. Real markets are near 3 (the inverse cubic "
            "law): a move twice as big is about 2³ = 8 times rarer. Smaller = fatter tails. A bell curve "
            "has no tail exponent; measured the same way it comes out near 6.",
    "kurtosis": "Excess kurtosis: 0 for a bell curve. Bigger = more very calm and very wild days.",
    "memory": "Volatility memory: correlation of move sizes a month (20 trading days) apart. 0 = no memory. "
              "Above 0 = wild days bunch together (volatility clustering).",
    "big": "Days that moved more than 4 standard deviations, either way.",
}


def setup():
    """Page-wide spacing and card style. Called once per run by app.py. st.html, not st.markdown:
    markdown read the [kind="primary"] selectors as link syntax and silently dropped them."""
    st.html(f"""<style>
    @import url('https://fonts.googleapis.com/css2?family=JetBrains+Mono:wght@400;600&display=swap');
    .block-container {{padding-top: 3.4rem; padding-bottom: 4rem; max-width: 1320px}}
    h1 {{font-size: 1.9rem !important; margin-bottom: .2rem !important; letter-spacing: -.01em}}
