def bell_big_days(n, size=BIG):
    """How many of n days a bell curve expects to move more than `size` standard deviations
    either way: n * P(|Z| > size) = n * erfc(size / sqrt 2)."""
    return n * math.erfc(size / math.sqrt(2))


def bell_tail(x):
    """Share of days a bell curve expects to move more than x standard deviations either way:
    P(|Z| > x) = erfc(x / sqrt 2). x may be one number or an array."""
    v = np.asarray(x, dtype=float)
    out = np.array([math.erfc(xi / math.sqrt(2)) for xi in v.ravel()]).reshape(v.shape)
    return float(out) if out.ndim == 0 else out


def summary(r):
    """The numbers the app shows for one series of daily returns."""
    if view == "Histogram":
        for label, rr, line in series:
            cx, d = ex.histogram(rr, empty=np.nan)        # NaN: an empty bin can't be drawn on a log scale
            fig.add_scatter(x=cx, y=d, name=label, mode="lines", line=line)
        g = np.linspace(-8, 8, 200)
        fig.add_scatter(x=g, y=np.exp(-g ** 2 / 2) / np.sqrt(2 * np.pi), name="Bell curve", mode="lines",
                        line=dict(color=c.BELL, dash="dot"))
        fig.update_yaxes(range=[-4.5, 0])
        return c.style(fig, 470, logy=True, xtitle="Daily move (standard deviations)", ytitle="How common (log)")

